// ========================================
// JWT TOKEN VALIDATION & USER AUTHENTICATION
// ========================================
const webhookData = $json;
const headers = webhookData.headers || {};

const authHeader = headers.authorization || headers.Authorization || '';
const token = authHeader.replace(/^Bearer\s+/i, '').trim();

if (!token) {
  throw new Error('UNAUTHORIZED: Missing authorization token');
}

try {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Invalid JWT format');

  const payload = JSON.parse(
    Buffer.from(parts[1].replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString()
  );

  const userId = payload.sub;
  const userEmail = payload.email;
  const exp = payload.exp;

  if (!userId || !userEmail) throw new Error('Invalid token: missing user information');

  const now = Math.floor(Date.now() / 1000);
  if (exp && exp < now) throw new Error('UNAUTHORIZED: Token expired');

  console.log('✅ JWT validated -', userEmail);

  return [{
    json: {
      userId, userEmail, authToken: token,
      ipAddress: headers['x-forwarded-for'] || 'unknown',
      userAgent: headers['user-agent'] || 'unknown',
      requestTimestamp: new Date().toISOString(),
      requestBody: webhookData.body || {},
      status: 'authenticated'
    }
  }];
} catch (error) {
  throw new Error('UNAUTHORIZED: ' + error.message);
}

const authData = $('1️⃣ JWT Validator').item.json;
const userProfile = $json[0];
if (!userProfile) throw new Error('User profile not found');

const requestBody = authData.requestBody;
const jobId = 'ugc_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

const binaryData = $binary;
let productImageBinary = null;
let binaryPropertyName = null;

if (binaryData && Object.keys(binaryData).length > 0) {
  binaryPropertyName = Object.keys(binaryData)[0];
  productImageBinary = binaryData[binaryPropertyName];
} else {
  throw new Error('No product image uploaded');
}

const ugcTypeMap = {
  'Holding Product - Natural pose': {style: 'natural', setting: 'home', emotion: 'confident', sceneStyle: 'casual handheld', cameraAngle: 'eye-level'},
  'Using Product - In action': {style: 'action', setting: 'lifestyle', emotion: 'satisfied', sceneStyle: 'dynamic usage', cameraAngle: 'slightly above'},
  'Unboxing - First impression': {style: 'excited', setting: 'home', emotion: 'surprised', sceneStyle: 'close-up unboxing', cameraAngle: 'top-down'},
  'Mirror Selfie - Authentic angle': {style: 'casual', setting: 'bedroom', emotion: 'happy', sceneStyle: 'mirror reflection', cameraAngle: 'selfie angle'},
  'Before & After - Transformation': {style: 'testimonial', setting: 'home', emotion: 'amazed', sceneStyle: 'split comparison', cameraAngle: 'direct to camera'},
  'Cozy at Home - Relaxed setting': {style: 'cozy', setting: 'living_room', emotion: 'relaxed', sceneStyle: 'lifestyle cozy', cameraAngle: 'warm intimate'},
  'Friend Sharing - Social moment': {style: 'social', setting: 'cafe', emotion: 'friendly', sceneStyle: 'candid social', cameraAngle: 'natural conversation'},
  'ASMR': {style: 'asmr', setting: 'quiet', emotion: 'calm', sceneStyle: 'close-up detailed', cameraAngle: 'macro focus'},
  'Podcast': {style: 'podcast', setting: 'studio', emotion: 'conversational', sceneStyle: 'interview setup', cameraAngle: 'medium shot'}
};

const ugcType = requestBody.ugcType || 'Holding Product - Natural pose';
const ugcConfig = ugcTypeMap[ugcType] || ugcTypeMap['Holding Product - Natural pose'];

const durationText = requestBody.duration || '16s Problem + Solution';
let duration = 16, totalScenes = 2;
if (durationText.includes('24s')) {duration = 24; totalScenes = 3;}
else if (durationText.includes('32s')) {duration = 32; totalScenes = 4;}
else if (durationText.includes('40s')) {duration = 40; totalScenes = 5;}
else if (durationText.includes('48s')) {duration = 48; totalScenes = 6;}
else if (durationText.includes('56s')) {duration = 56; totalScenes = 7;}
else if (durationText.includes('64s')) {duration = 64; totalScenes = 8;}

const platform = requestBody.platform || 'TikTok/Reels (9:16)';
let aspectRatio = '9:16';
if (platform.includes('16:9')) aspectRatio = '16:9';
else if (platform.includes('1:1')) aspectRatio = '1:1';

const targetAudience = requestBody.targetAudience || 'Gen Z (18-24)';

const output = {
  jobId, requestId: jobId, userId: authData.userId, userEmail: authData.userEmail,
  subscriptionTier: userProfile.subscription_tier, creditsBalance: userProfile.credits_balance,
  productName: requestBody.productName || 'Product',
  productDescription: requestBody.productDescription || '',
  ugcType, ugcConfig, duration, totalScenes,
  sceneDuration: duration === 64 ? 8 : (duration / totalScenes),
  aspectRatio, platform, targetAudience, creditsCost: 10,
  productImageFile: {
    fileName: productImageBinary.fileName,
    mimeType: productImageBinary.mimeType,
    fileSize: productImageBinary.fileSize,
    binaryPropertyName
  },
  ipAddress: authData.ipAddress, userAgent: authData.userAgent,
  status: 'validated', timestamp: authData.requestTimestamp
};

console.log('✅ Validated -', authData.userEmail, '- Job:', jobId);
return [{json: output, binary: binaryData}];

