const aiOutput = $json.output;
const uploadData = $('7️⃣ Upload Image').item.json;
const baseData = $('4️⃣ Validate Input').item.json;
const jobData = $('5️⃣ Create Job').item.json[0];

let gridStrategy;
try {
  let cleanText = aiOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = cleanText.indexOf('{');
  const end = cleanText.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    cleanText = cleanText.substring(start, end + 1);
  }
  gridStrategy = JSON.parse(cleanText);
  console.log('✅ Grid strategy parsed -', gridStrategy.productAnalysis.category);
} catch (error) {
  console.warn('⚠️ Parse failed, using fallback');
  gridStrategy = {
    productAnalysis: {category: 'general', subtype: baseData.productName, presentationStyle: 'professional'},
    nanoBananaPrompt: `Professional product photography, 2x2 grid layout showing ${baseData.productName}:\n\nTOP-LEFT: Front view - product facing camera directly, all branding visible, centered\nTOP-RIGHT: 45-degree angle - shows depth and dimension, side details visible\nBOTTOM-LEFT: Top-down overhead - complete product shape from above\nBOTTOM-RIGHT: Detail close-up - macro shot of key feature or texture\n\nREQUIREMENTS: All 4 cells show EXACT SAME product, perfect 2x2 grid, pure white background (#FFFFFF), professional studio lighting, thin white borders (5px), ultra high resolution, e-commerce quality, consistent scale, no text overlays.`
  };
}

const nanoBananaPayload = {
  model: "nano-banana-pro",
  input: {
    prompt: gridStrategy.nanoBananaPrompt,
    image_input: [uploadData.data.downloadUrl],
    aspect_ratio: "1:1",
    resolution: "2K",
    output_format: "png"
  }
};

const output = {
  jobDatabaseId: jobData.id,
  jobId: baseData.jobId,
  productName: baseData.productName,
  productImageUrl: uploadData.data.downloadUrl,
  productAnalysis: gridStrategy.productAnalysis,
  nanoBananaPayload,
  gridPrompt: gridStrategy.nanoBananaPrompt,
  status: 'grid_generation',
  progress: 15
};

console.log('✅ Nano-Banana payload ready');
return [{json: output}];

const taskId = $('9️⃣ Create Grid').item.json.data.taskId;
const MAX_RETRIES = 20;
const WAIT_TIME = 10;

console.log('⏳ Waiting for grid generation...');

for (let i = 0; i < MAX_RETRIES; i++) {
  const response = await $http.get(
    `https://api.kie.ai/api/v1/jobs/recordInfo?taskId=${taskId}`,
    {headers: {'Authorization': 'Bearer ' + process.env.KIE_API_KEY}}
  );

  const state = response.data?.data?.state;

  if (state === 'success') {
    console.log('✅ Grid generated');
    return [{json: response.data}];
  }
  if (state === 'failed') {
    throw new Error('Grid generation failed: ' + response.data?.data?.failMsg);
  }

  await new Promise(resolve => setTimeout(resolve, WAIT_TIME * 1000));
}

throw new Error('Grid generation timeout');

const kieResponse = $json;
const gridData = $('8️⃣ Parse Grid').item.json;

if (kieResponse.data.state !== 'success') {
  throw new Error('Grid not successful');
}

let gridImageUrl;
try {
  const resultData = JSON.parse(kieResponse.data.resultJson);
  gridImageUrl = resultData.resultUrls[0];
} catch (error) {
  throw new Error('Failed to extract grid URL');
}

const output = {
  jobDatabaseId: gridData.jobDatabaseId,
  jobId: gridData.jobId,
  productName: gridData.productName,
  productAnalysis: gridData.productAnalysis,
  productImages: {
    original: gridData.productImageUrl,
    grid2x2: gridImageUrl,
    referenceUrls: [gridData.productImageUrl, gridImageUrl]
  },
  status: 'character_selection',
  progress: 30
};

console.log('✅ Grid URL:', gridImageUrl);
return [{json: output}];

const baseData = $('4️⃣ Validate Input').item.json;
const gridData = $('1️⃣1️⃣ Extract Grid').item.json;
const targetAudience = baseData.targetAudience;

const characterModels = {
  'Gen Z (18-24)': {
    ages: [18, 19, 20, 21, 22, 23, 24],
    styles: ['trendy', 'vibrant', 'casual', 'streetwear'],
    settings: ['urban', 'cafe', 'bedroom'],
    hairStyles: ['modern', 'colorful highlights', 'styled messy'],
    makeup: ['natural dewy', 'bold liner', 'minimal fresh'],
    clothing: ['oversized hoodie', 'crop top', 'denim jacket'],
    vibe: 'energetic and authentic',
    lighting: 'natural window light'
  },
  'Millennials (25-40)': {
    ages: [25, 28, 30, 32, 35, 38],
    styles: ['smart-casual', 'professional', 'minimalist'],
    settings: ['home-office', 'kitchen', 'living-room'],
    hairStyles: ['professional', 'neat', 'well-groomed'],
    makeup: ['polished natural', 'professional'],
    clothing: ['button-up shirt', 'sweater', 'quality basics'],
    vibe: 'relatable and trustworthy',
    lighting: 'balanced home lighting'
  },
  'Gen X (41-55)': {
    ages: [42, 45, 48, 50, 52, 55],
    styles: ['classic', 'mature', 'elegant'],
    settings: ['home', 'garden', 'comfortable-office'],
    hairStyles: ['classic', 'mature', 'distinguished'],
    makeup: ['sophisticated', 'age-appropriate'],
    clothing: ['quality knit', 'tailored shirt', 'cardigan'],
    vibe: 'experienced and credible',
    lighting: 'soft natural light'
  },
  'All Ages': {
    ages: [25, 30, 35, 40],
    styles: ['universal', 'friendly', 'approachable'],
    settings: ['neutral', 'home', 'everyday'],
    hairStyles: ['versatile', 'natural'],
    makeup: ['neutral', 'fresh'],
    clothing: ['casual shirt', 'comfortable wear'],
    vibe: 'broadly appealing',
    lighting: 'balanced natural'
  },
  'Business/Professional': {
    ages: [30, 35, 40, 45],
    styles: ['corporate', 'business-casual', 'executive'],
    settings: ['office', 'modern-workspace'],
    hairStyles: ['professional', 'polished'],
    makeup: ['professional', 'confident'],
    clothing: ['blazer', 'dress shirt'],
    vibe: 'authoritative and professional',
    lighting: 'professional office lighting'
  }
};

const audienceProfile = characterModels[targetAudience] || characterModels['Gen Z (18-24)'];

const productStr = baseData.productName.toLowerCase();
let hash = 0;
for (let i = 0; i < productStr.length; i++) {
  hash = ((hash << 5) - hash) + productStr.charCodeAt(i);
  hash = hash & hash;
}
const baseSeed = Math.abs(hash) % 900000 + 100000;

const selectedAge = audienceProfile.ages[baseSeed % audienceProfile.ages.length];
const selectedGender = (baseSeed % 2 === 0) ? 'Female' : 'Male';
const selectedStyle = audienceProfile.styles[baseSeed % audienceProfile.styles.length];
const selectedHairStyle = audienceProfile.hairStyles[baseSeed % audienceProfile.hairStyles.length];
const selectedMakeup = audienceProfile.makeup[baseSeed % audienceProfile.makeup.length];
const selectedClothing = audienceProfile.clothing[baseSeed % audienceProfile.clothing.length];

const characterPrompt = `${selectedAge}-year-old ${selectedGender}, ${audienceProfile.vibe}, ${selectedStyle} style, ${selectedHairStyle} hair, ${selectedMakeup} makeup, wearing ${selectedClothing}, ${audienceProfile.lighting}, UGC authentic feel, iPhone quality, natural genuine`;

const output = {
  jobDatabaseId: gridData.jobDatabaseId,
  jobId: gridData.jobId,
  productName: gridData.productName,
  productImages: gridData.productImages,
  productAnalysis: gridData.productAnalysis,

  characterModel: {
    gender: selectedGender,
    age: selectedAge,
    style: selectedStyle,
    setting: audienceProfile.settings[0],
    hairStyle: selectedHairStyle,
    makeup: selectedMakeup,
    clothing: selectedClothing,
    vibe: audienceProfile.vibe,
    lighting: audienceProfile.lighting,
    prompt: characterPrompt
  },

  baseSeed,
  audienceProfile: {
    name: targetAudience,
    vibe: audienceProfile.vibe
  },

  status: 'character_selected',
  progress: 40
};

console.log('✅ Character:', selectedAge, selectedGender, selectedStyle, '- Seed:', baseSeed);
return [{json: output}];
